NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'Ruth'

CHAPTERS = {
    1: {
        1: 'Siihen aikaan kun tuomarit hallitsivat, maahan tuli nälänhätä. Silloin muuan Juudan Beetlehemin mies lähti sieltä ja asettui vaimonsa ja kahden poikansa kanssa asumaan muukalaisena Mooabin maahan.',
        2: 'Miehen nimi oli Elimelek, hänen vaimonsa nimi Noomi ja hänen kahden poikansa nimet Mahlon ja Kiljon. He olivat efratilaisia Juudan Beetlehemistä. He tulivat Mooabin maahan ja oleskelivat siellä.',
        3: 'Elimelek, Noomin mies, kuoli, ja Noomi jäi elämään kahden poikansa kanssa.',
        4: 'Nämä ottivat itselleen mooabilaiset vaimot. Toisen nimi oli Orpa ja toisen nimi Ruut. He asuivat siellä noin kymmenen vuotta.',
        5: 'Sitten myös molemmat, Mahlon ja Kiljon, kuolivat, niin että vaimo jäi yksin jäljelle kahden poikansa ja miehensä kuoltua.',
        6: 'Hän nousi miniöineen palatakseen Mooabin maasta, sillä hän oli kuullut Mooabin maassa, että Herra oli pitänyt kansastaan huolen ja antanut sille leipää.',
        7: 'Hän lähti yhdessä molempien miniöidensä kanssa siitä paikasta, jossa oli oleskellut. Heidän tietä käydessään matkalla Juudan maahan',
        8: 'Noomi sanoi molemmille miniöilleen: "Menkää, palatkaa kumpikin äitinne kotiin. Herra tehköön teille laupeuden, kuten olette tehneet vainajille ja minulle.',
        9: 'Herra suokoon, että saisitte turvan kumpikin miehenne kodissa." Sitten hän suuteli heitä. Mutta he korottivat äänensä ja itkivät',
        10: 'ja sanoivat hänelle: "Me palaamme kanssasi kansasi luo."',
        11: 'Mutta Noomi vastasi: "Kääntykää takaisin, tyttäreni, miksi lähtisitte kanssani? Voinko minä enää saada poikia miehiksi teille?',
        12: "Kääntykää takaisin, tyttäreni, menkää, sillä minä olen liian vanha mennäkseni miehelle. Vaikka ajattelisinkin: 'Minulla on vielä toivoa', ja vaikka vielä tänä yönä tulisin miehelle vaimoksi ja synnyttäisin poikia,",
        13: 'ette kai te kuitenkaan odottaisi, kunnes he kasvaisivat suuriksi, ette kai te kuitenkaan sulkeutuisi huoneeseen ja olisi menemättä miehelle vaimoksi. Ei, tyttäreni. Minä olen hyvin murheissani tähtenne, sillä Herran käsi on koskenut minuun."',
        14: 'Niin he korottivat vielä äänensä ja itkivät. Silloin Orpa suuteli anoppiaan jäähyväisiksi, mutta Ruut riippui hänessä kiinni.',
        15: 'Noomi sanoi: "Katso, kälysi on kääntynyt takaisin oman kansansa ja jumalansa luo, käänny sinäkin kälysi kanssa."',
        16: 'Mutta Ruut vastasi: "Älä vaadi minua jättämään sinua ja kääntymään takaisin, pois luotasi. Sillä mihin sinä menet, sinne minäkin menen, ja missä sinä yövyt, siellä minäkin yövyn. Sinun kansasi on minun kansani, sinun Jumalasi on minun Jumalani.',
        17: 'Missä sinä kuolet, siellä minäkin tahdon kuolla ja tulla sinne haudatuksi. Herra rangaiskoon minua nyt ja vasta, jos muu kuin kuolema erottaa meidät."',
        18: 'Kun Noomi näki, että hän oli lujasti päättänyt seurata häntä, hän ei enää puhunut siitä hänen kanssaan.',
        19: 'Niin he kulkivat molemmat yhdessä, kunnes tulivat Beetlehemiin. Kun he tulivat Beetlehemiin, koko kaupunki joutui liikkeelle heidän tähtensä, ja vaimot sanoivat: "Onko tämä Noomi?"',
        20: 'Mutta hän vastasi heille: "Älkää kutsuko minua Noomiksi, kutsukaa minua Maaraksi, sillä Kaikkivaltias on antanut minulle paljon katkeraa murhetta.',
        21: 'Rikkaana minä lähdin, mutta tyhjänä Herra antaa minun palata. Miksi siis kutsutte minua Noomiksi, kun Herra on todistanut minua vastaan ja Kaikkivaltias on tuottanut onnettomuutta minulle?"',
        22: 'Niin Noomi oli palannut miniänsä, mooabilaisen Ruutin, kanssa, joka tuli Mooabin maasta. He olivat saapuneet Beetlehemiin ohranleikkuun alussa.',
    },
    2: {
        1: 'Noomilla oli miehensä puolelta sukulainen, hyvin varakas mies, Elimelekin sukua, nimeltä Booas.',
        2: 'Mooabilainen Ruut sanoi Noomille: "Anna minun mennä pellolle poimimaan tähkiä jonkun jäljessä, jonka silmien edessä saan armon." Noomi vastasi hänelle: "Mene, tyttäreni!"',
        3: 'Niin hän lähti ja meni poimimaan eräälle pellolle leikkuuväen jäljessä. Niin hänelle kävi niin, että se peltopalsta oli Booaan, joka oli Elimelekin sukua.',
        4: 'Silloin, katso, Booas tuli Beetlehemistä ja sanoi leikkuuväelle: " Herra olkoon kanssanne!" He vastasivat hänelle: " Herra siunatkoon sinua!"',
        5: 'Sitten Booas sanoi palvelijalleen, joka oli leikkuuväen päällysmiehenä: "Kenen tuo nuori nainen on?"',
        6: 'Palvelija, joka oli leikkaajien päämiehenä, vastasi ja sanoi: "Se on nuori mooabitar, joka tuli Noomin mukana Mooabin maasta.',
        7: 'Ruut sanoi: \'Salli minun poimia ja koota tähkiä lyhteiden väliltä leikkaajien jäljessä.\' Niin hän tuli ja on ahertanut aamusta varhain tähän saakka. Vasta äsken hän hiukan levähti tuolla majassa."',
        8: 'Niin Booas sanoi Ruutille: "Kuule, tyttäreni! Älä mene muiden pelloille poimimaan äläkä lähde pois täältä, vaan pysy täällä palvelijattarieni mukana.',
        9: 'Pidä silmällä, millä pellolla leikataan, ja kulje heidän perässään. Olen kieltänyt palvelijoitani koskemasta sinuun. Jos sinun tulee jano, mene astioille ja juo vettä, jota palvelijat ammentavat."',
        10: 'Ruut heittäytyi kasvoilleen, kumartui maahan ja sanoi hänelle: "Miten olen saanut armon silmiesi edessä, niin että huolehdit minusta, vaikka olen vieras?"',
        11: 'Booas vastasi ja sanoi hänelle: "Minulle on kerrottu kaikki, mitä olet tehnyt anopillesi miehesi kuoltua, kuinka jätit isäsi ja äitisi ja synnyinmaasi ja lähdit kansan luo, jota et ennen tuntenut.',
        12: 'Herra palkitkoon sinulle tekosi. Tulkoon sinulle täysi palkka Herralta, Israelin Jumalalta, jonka siipien alta olet tullut etsimään turvaa."',
        13: 'Ruut sanoi: "Minä olen saanut armon silmiesi edessä, herrani, sillä sinä olet lohduttanut minua ja puhutellut palvelijatartasi ystävällisesti, vaikka en ole yhdenkään palvelijattaresi vertainen."',
        14: 'Ruoka-ajan tultua Booas sanoi hänelle: "Tule tänne syömään leipää ja kasta palasesi hapanviiniin." Ruut istui viljan leikkaajien viereen. Booas pani hänen eteensä paahdettuja jyviä, niin että hän söi tarpeekseen ja jäi tähteeksikin.',
        15: 'Kun hän sitten nousi poimimaan, Booas käski palvelijoitaan sanoen: "Hän saa poimia myös lyhteiden väliltä, ettekä te saa loukata häntä.',
        16: 'Voittepa vetää lyhteistäkin joitakin tähkiä ja jättää ne hänen poimittavikseen, ettekä saa nuhdella häntä."',
        17: 'Ruut poimi pellolla iltaan asti. Sitten hän pui, mitä oli saanut poimituksi, ja siitä tuli noin eefa-mitan verran ohria.',
        18: 'Hän otti ne, tuli kaupunkiin ja näytti anopilleen, mitä oli poiminut. Sen jälkeen Ruut otti esille tähteet ruuasta, josta oli syönyt tarpeekseen, ja antoi ne hänelle.',
        19: 'Silloin hänen anoppinsa sanoi hänelle: "Missä olet tänään poiminut ja missä olet tehnyt työtä? Siunattu olkoon se, joka on sinusta huolehtinut." Sitten hän ilmoitti anopilleen, kenen luona hän oli ollut työssä, sanoen: "Se mies, jonka luona olin tänä päivänä työssä, on nimeltään Booas."',
        20: 'Noomi sanoi miniälleen: "Siunatkoon häntä Herra, joka on osoittanut laupeutta eläviä ja kuolleita kohtaan." Noomi sanoi vielä: "Hän on sukulaisemme ja sukulunastajiamme."',
        21: 'Silloin mooabilainen Ruut sanoi: "Vielä hän sanoi minulle: \'Pysyttele vain palvelijoitteni mukana siihen asti, että he saavat päätökseen kaiken leikkuuni.\'"',
        22: 'Niin Noomi sanoi miniälleen Ruutille: "Hyvä on, tyttäreni, lähde hänen palvelijattariensa mukana, niin et joudu tönittäväksi muiden pelloilla."',
        23: 'Hän pysytteli Booaan palvelijattarien seurassa poimien tähkiä, kunnes ohran- ja vehnänleikkuu oli lopussa. Sitten hän jäi asumaan anoppinsa luo.',
    },
    3: {
        1: 'Niin Noomi, hänen anoppinsa, sanoi hänelle: "Tyttäreni, minäpä hankin sinulle turvapaikan, että sinun kävisi hyvin.',
        2: 'Onhan Booas, jonka palvelijattarien kanssa olit, sukulaisemme. Katso, hän viskaa tänä yönä ohria puimatantereella.',
        3: 'Niin peseydy nyt, voitele itsesi, pukeudu ja mene puimatantereelle. Mutta älä näyttäydy hänelle, ennen kuin hän on syönyt ja juonut.',
        4: 'Kun hän panee maata, niin, katso, mihin paikkaan hän panee maata, ja mene ja nosta peitettä hänen jalkojensa kohdalta ja pane siihen maata. Hän sanoo sitten sinulle, mitä sinun on tehtävä."',
        5: 'Ruut vastasi hänelle: "Teen kaiken, mitä sanot."',
        6: 'Hän meni alas puimatantereelle ja teki aivan niin, kuin hänen anoppinsa oli häntä käskenyt.',
        7: 'Kun Booas oli syönyt ja juonut, tuli hänen sydämensä iloiseksi, ja hän meni maata viljakasan viereen. Ruut tuli hiljaa ja nosti peitettä hänen jalkojensa kohdalta ja pani siihen maata.',
        8: 'Puoliyön aikaan mies säikähti ja kumartui eteenpäin. Niin, katso, nainen makasi hänen jalkopäässään.',
        9: 'Hän kysyi: "Kuka sinä olet?" Hän vastasi: "Minä olen Ruut, palvelijattaresi. Levitä helmasi palvelijattaresi yli, sillä sinä olet sukulunastajani."',
        10: 'Hän sanoi: " Herra siunatkoon sinua, tyttäreni! Sinä olet osoittanut sukurakkauttasi nyt viimeksi vielä kauniimmin kuin aikaisemmin, kun et ole kulkenut nuorten miesten jäljessä, et köyhien etkä rikkaitten.',
        11: 'Nyt, tyttäreni, älä pelkää. Kaiken, mitä sanot, teen sinulle. Sillä kansani portissa jokainen tietää sinut kunnialliseksi naiseksi.',
        12: 'Totta on, että olen sukulunastajasi, mutta on vielä toinen sukulunastaja, joka on läheisempi kuin minä.',
        13: 'Jää tähän yöksi. Jos hän huomenna lunastaa sinut, niin hyvä, lunastakoon. Mutta jollei hän halua lunastaa sinua, niin minä lunastan sinut, niin totta kuin Herra elää. Lepää siinä aamuun asti."',
        14: 'Niin hän lepäsi hänen jalkopäässään aamuun asti, mutta nousi, ennen kuin kukaan vielä voi tuntea toisensa. Booas ajatteli: "Älköön tulko tietoon, että tuo nainen on tullut tänne puimatantereelle."',
        15: 'Hän sanoi: "Anna tänne viitta, joka on ylläsi, ja pidä siitä kiinni." Niin Ruut piti siitä kiinni. Silloin hän mittasi siihen kuusi mittaa ohria ja pani ne hänen selkäänsä. Sitten Ruut meni kaupunkiin.',
        16: 'Ruut tuli anoppinsa luo, joka sanoi: "Kuinka kävi, tyttäreni?" Niin hän kertoi hänelle kaikki, mitä mies oli hänelle tehnyt.',
        17: 'Hän sanoi: "Nämä kuusi mittaa ohria hän antoi minulle, sanoen: \'Et saa mennä tyhjin käsin anoppisi luo.\'"',
        18: 'Silloin Noomi sanoi: "Pysy alallasi, tyttäreni, kunnes saat tietää, kuinka asia päättyy; sillä mies ei suo itselleen lepoa, ennen kuin hän tänä päivänä saattaa asian päätökseen."',
    },
    4: {
        1: 'Mutta Booas meni kaupungin porttiin ja istuutui sinne. Katso, sukulunastaja, josta Booas oli puhunut, kulki siitä ohitse. Booas sanoi: "Sinä siellä, poikkea tänne istumaan." Hän poikkesi ja istui siihen.',
        2: 'Sen jälkeen Booas otti kaupungin vanhimpia kymmenen miestä ja sanoi: "Istukaa tähän." Niin he istuivat.',
        3: 'Sitten Booas sanoi sukulunastajalle: "Sen peltopalstan, joka oli veljellämme Elimelekillä, Noomi, joka on palannut Mooabin maasta, haluaa myydä.',
        4: 'Sen tähden minä ajattelin: ilmoitan siitä sinulle ja sanon: osta se tässä saapuvilla olevien ja kansani vanhimpien läsnä ollessa. Jos tahdot sen lunastaa sukuun, niin lunasta. Mutta ellet tahdo sitä lunastaa, ilmoita minulle, että saan sen tietää. Sillä ei ole ketään muuta sukulunastajaa kuin sinä, ja sinun jälkeesi minä." Hän sanoi: "Minä lunastan sen."',
        5: 'Niin Booas sanoi: "Ostaessasi pellon Noomilta ostat sen myös mooabilaiselta Ruutilta, vainajan leskeltä, ja sinun on pysytettävä vainajan nimi hänen perintöosassaan."',
        6: 'Silloin sukulunastaja sanoi: "En voi lunastaa sitä itselleni, sillä siten turmelisin oman perintöosani. Lunasta sinä itsellesi, mitä minun olisi lunastettava, sillä en voi sitä lunastaa."',
        7: 'Muinoin oli Israelissa lunastus- ja vaihtokauppoja vahvistettaessa tällainen tapa: riisuttiin sandaali ja annettiin toiselle. Tätä käytettiin Israelissa todisteena.',
        8: 'Sukulunastaja sanoi Booaalle: "Osta sinä se itsellesi." Ja hän veti kengän jalastaan.',
        9: 'Silloin Booas sanoi vanhimmille ja kaikelle kansalle: "Te olette tänään todistajina, että ostan Noomilta kaiken Elimelekin ja kaiken Kiljonin ja Mahlonin omaisuuden.',
        10: 'Samalla minä olen ostanut myös mooabilaisen Ruutin, Mahlonin lesken, vaimokseni, pysyttääkseni vainajan nimen hänen perintöosassaan, ettei vainajan nimi häviäisi hänen veljiensä keskuudesta eikä hänen kotipaikkansa portista. Sen todistajia te olette tänä päivänä."',
        11: 'Niin kaikki kansa, joka oli portissa saapuvilla, ja vanhimmat sanoivat: "Me olemme sen todistajia. Suokoon Herra, että vaimo, joka tulee taloosi, tulisi Raakelin ja Leean kaltaiseksi, jotka molemmat rakensivat Israelin huoneen. Tee väkeviä tekoja Efratassa ja saata nimesi kuuluisaksi Beetlehemissä.',
        12: 'Tulkoon niistä jälkeläisistä, jotka Herra antaa sinulle tästä nuoresta naisesta, sinulle suku, Pereksen suvun kaltainen, hänen, jonka Taamar synnytti Juudalle."',
        13: 'Niin Booas otti Ruutin, ja tämä tuli hänen vaimokseen. Hän yhtyi häneen. Herra antoi hänen tulla raskaaksi, ja hän synnytti pojan.',
        14: 'Silloin vaimot sanoivat Noomille: "Kiitetty olkoon Herra, joka tänä päivänä salli sinun saada sukulunastajan. Hänen nimensä tulee kuuluisaksi Israelissa.',
        15: 'Hän on virvoittava sinua, ja hänestä on tuleva vanhuutesi tuki, sillä miniäsi, joka rakastaa sinua, on hänet synnyttänyt, hän, joka on sinulle parempi kuin seitsemän poikaa."',
        16: 'Niin Noomi otti lapsen, pani sen helmaansa ja rupesi sen hoitajaksi.',
        17: 'Naapurivaimot antoivat lapselle nimen, sanoen: "Noomille on syntynyt poika." He panivat hänelle nimeksi Oobed. Hänestä tuli Daavidin isän, Iisain, isä.',
        18: 'Tämä on Pereksen sukuluettelo: Perekselle syntyi Hesron.',
        19: 'Hesronille syntyi Raam, ja Raamille syntyi Amminadab.',
        20: 'Amminadabille syntyi Nahson, ja Nahsonille syntyi Salma.',
        21: 'Salmalle syntyi Booas, ja Booaalle syntyi Oobed.',
        22: 'Oobedille syntyi Iisai, ja Iisaille syntyi Daavid.',
    },
}
